TLM.f("Sancti/08-09t",{"officium":"In Vigilia S. Laurentii Mart.","rule":["vide C2;","no Gloria","Suffragium=Maria3;Papa;Ecclesia;;"],"fallback":"Commune/C2","from":{"GradualeP":"Commune/C2","Tractus":"Commune/C2"},"sections":{"Introitus":[{"k":"ref","la":"Ps 111:9"},{"k":"text","la":"Dispérsit, dedit paupéribus: justítia ejus manet in sǽculum sǽculi: cornu ejus exaltábitur in glória."},{"k":"ref","la":"Ps 111:1"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Dispérsit, dedit paupéribus: justítia ejus manet in sǽculum sǽculi: cornu ejus exaltábitur in glória."}],"Oratio":[{"k":"text","la":"Adésto, Dómine, supplicatiónibus nostris: et intercessióne beáti Lauréntii Mártyris tui, cujus prævénimus festivitátem; perpétuam nobis misericórdiam benígnus impénde."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 51:1-8; 51:12"},{"k":"text","la":"Confitébor tibi, Dómine, Rex, et collaudábo te Deum, Salvatórem meum. Confitébor nómini tuo: quóniam adjútor et protéctor factus es mihi, et liberásti corpus meum a perditióne, a láqueo linguæ iníquæ et a lábiis operántium mendácium, et in conspéctu astántium factus es mihi adjútor. Et liberásti me secúndum multitúdinem misericórdiæ nóminis tui a rugiéntibus, præparátis ad escam, de mánibus quæréntium ánimam meam, et de portis tribulatiónum, quæ circumdedérunt me: a pressúra flammæ, quæ circúmdedit me, et in médio ignis non sum æstuátus: de altitúdine ventris ínferi, et a lingua coinquináta, et a verbo mendácii, a rege iníquo, et a lingua injústa: laudábit usque ad mortem ánima mea Dóminum: quóniam éruis sustinéntes te, et líberas eos de mánibus géntium, Dómine, Deus noster."}],"Graduale":[{"k":"ref","la":"Ps 111:9; 111:2"},{"k":"text","la":"Dispersit, dedit paupéribus: justítia ejus manet in sǽculum sǽculi."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: étenim veritátem tuam in ecclésia sanctórum. Allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 111:1-2"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 20:3-4"},{"k":"text","la":"Desidérium ánimæ ejus tribuísti ei: et voluntáte labiórum ejus non fraudásti eum."},{"k":"text","la":"Quóniam prævenísti eum in benedictiónibus dulcédinis.","mark":"V"},{"k":"text","la":"Posuísti in cápite ejus corónam de lápide pretióso.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 16:24-27"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Si quis vult post me veníre, ábneget semetípsum, et tollat crucem suam, et sequátur me. Qui enim volúerit ánimam suam salvam fácere, perdet eam: qui autem perdíderit ánimam suam propter me, invéniet eam. Quid enim prodest hómini, si mundum univérsum lucrétur, ánimæ vero suæ detriméntum patiátur? Aut quam dabit homo commutatiónem pro ánima sua? Fílius enim hóminis ventúrus est in glória Patris sui cum Angelis suis: et tunc reddet unicuíque secúndum ópera ejus."}],"Offertorium":[{"k":"ref","la":"Job 16:20"},{"k":"text","la":"Orátio mea munda est: et ídeo peto, ut detur locus voci meæ in cœlo: quia ibi est judex meus, et cónscius meus in excélsis: ascéndat ad Dóminum deprecátio mea."}],"Secreta":[{"k":"text","la":"Hóstias, Dómine, quas tibi offérimus, propítius súscipe: et, intercédente beáto Lauréntio Mártyre tuo, víncula peccatórum nostrórum absólve."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 16:24"},{"k":"text","la":"Qui vult veníre post me, ábneget semetípsum, et tollat crucem suam, et sequátur me."}],"Postcommunio":[{"k":"text","la":"Da, quǽsumus, Dómine, Deus noster: ut, sicut beáti Lauréntii Mártyris tui commemoratióne, temporáli gratulámur offício; ita perpétuo lætémur aspéctu."},{"k":"macro","name":"Per Dominum"}]},"hr":{"fa1d1cb65bfa5d86":{"t":"Ps 111, 9, Ps 111, 1\n(Ps 111, 9) Obilno je dijelio i davao siromasima, pravda njegova ostaje dovijeka, uzdići će se snaga i slava njegova. (Ps 111, 1) Blago čovjeku koji se boji Gospodina, koji se veoma raduje njegovim zapovijedima.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 111, 9) Obilno je dijelio i davao siromasima, pravda njegova ostaje dovijeka, uzdići će se snaga i slava njegova."},"9268025777640b5e":{"t":"<i>Pomolimo se</i>.\nMilostiv budi, Gospodine, našim poniznim molbama i dobrostivo nam daj vječno milosrđe po zagovoru blaženoga Lovre mučenika tvoga, kojega blagdan očekujemo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Cuj, Gospodine, molitve naše i zagovorom blaženog Lovre, Tvoga mučenika, kojega pretječemo evetkovinu, udijeli nam milostivo vječn-o miilosrđe.","knRef":"Kniewald 1942, str. 674–675 (snimka 338) (OCR)"},"2203abed977eae7c":{"t":"Sir 51, 1-8 i 12\nČitanje knjige Mudrosti. Slavim te, Gospodine Kralju, i hvalim te, Bože, Spasitelju moj. Slavim ime tvoje, jer si postao mojim pomoćnikom i zaštitnikom, spasio si me od propasti od zamke opaka jezika i od usta koja govore laži, i stao si uza me protiv mojih neprijatelja. Po svojem velikom milosrđu oslobodio si me od progonitelja, koji riču i spremni su da me prožderu. iz ruku onih koji vrebaju na me, iz muka koje me okružuju, od sile plamena koji me opkolio i nisam izgorio u ognju, iz dubine ponora, od opakog jezika i lažnih riječi, od pakosnoga poglavice i nepravednih usta. Hvalit ću te Gospodine, sve do smrti, jer ti spašavaš one koji se uzdaju u tebe, i oslobađaš ih iz bezbožničkih ruku, Gospodine naš.","kn":"Čitanje Knjige mudrosti (Crkv. 51, 1-8. 12). Slavim te, Gospodine kralju, i hvalim te. Bože, moj Spasitelju. Slavim tvoje ime, jer si postao moj pomoćnik i zaštitnik i spasio si me od propasti, od zamke opaka jezika i od usana, koje govore laži i stao si uza me protiv mojih protivnika. I ipo velikom svom milosrđu oslobodio si me od neprijatelja, koji riču spremni, da me prožderu; iz ruku onih, koji vrebaju na me i iz muka, koje me okružuju; od sile plamena, koji me je opkolio, da nijesam izgorjela u ognju; iz dubine ponora, od pogana jezika i lažnih riječi, od pakosna kralja i nepravedna jezika. Hvalit ću te. Gospodine, sve do smrti, jer spašavaš one, koji se uzdaju u tebe i oslobađaš ih iz bezbožničkih ruku, Gospodine Bože najš.","knRef":"Kniewald 1942, str. 830–831 (snimka 416) (OCR)"},"a53a3a9865abaf0b":{"t":"Ps 111, 9 i 2\nObilno je dijelio i davao siromasima, pravda njegova ostaje dovijeka. Jako će bili na zemlji potomstvo njegovo, rod će pravednika biti blagoslovljen.","kn":"(Ps. 111, 9). Rasu, razda utiogiima, pravda njegova ostaje u vijek vijeka. Silino će biti na zemlji potomstvo njego'vo, blagoslovit će se rod pravednih.","knRef":"Kniewald 1942, str. 682–683 (snimka 342) (OCR)"},"3068222c7b7795b6":{"t":"Mt 16, 24-27\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus svojim učenicima: Ako tko hoće da ide za mnom, neka se odreče sebe, uzme svoj križ i pođe za mnom. Tko hoće spasiti svoj život izgubit će ga, a tko izgubi svoj život radi mene naći će ga. Što koristi čovjeku, ako dobije čitav svijet, a izgubi svoju dušu? Kakvu će zamjenu čovjek dati za svoju dušu? Sin će Čovječji doći u slavi svoga Oca s anđelima, i tada će svakome naplatiti po njegovim djelima.","kn":"t Slijedi sv. evanđelje po Matejii (16, 24-27). U ono vrijeme reče Isus svojim učenicima: Ako tko hoće da ide za mnom, neka se odreče samoga sebe, uzme svoj križ i slijedi me. Tko hoće da spasi svoj život,, izgubit će ga, a tko izgubi svoj život radi mene, naći će ga. Jer što koristi čovjeku, ako dobije sav svijet, a izgubi svoju dušu? Ili kakvu će zamjenu dati čovjek za svoju dušu? Jer će Sin čovječji doći u slavi svoga Oca sa svojim anđelima i tada će svakomu platiti po njegovim djelima. ^","knRef":"Kniewald 1942, str. 792–793 (snimka 397) (OCR)"},"4c0ee4428460f623":{"t":"Job 16, 20\nMoja je molitva čista. Stoga želim da moj glas dopre do neba. Gore je moj sudac i moj svjedok. Neka se digne ka Gospodinu molitva moja."},"fd200cd1ec1c5713":{"t":"Gospodine, milostivo primi darove koje ti prikazujemo i po zagovoru blaženoga Lovre mučenika tvoga odriješi okove naših grijeha.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, Gospodine, milostivo žrtve, što Ti ih prikazujemo, i odriješi nas zagovorom blaženog mučenika svoga Lovre, od svih okova naših grijeha.","knRef":"Kniewald 1942, str. 674–675 (snimka 338) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"86afb01737f7cc30":{"t":"Mt 16, 24\nTko hoće da ide za mnom, neka se odreče samoga sebe, neka uzme križ svoj i slijedi mene.","kn":"(Mat. 16, 34). Ako tko hoće za mnom da ide, neka se odreče samoga sebe, neka uzme križ svoj i neka ide za mnom.","knRef":"Kniewald 1942, str. 794–795 (snimka 398) (OCR)"},"1c664301f5a7a83f":{"t":"<i>Pomolimo se</i>.\nDaj, molimo, Gospodine, kao što radosno slavimo u vremenu bogoslužje na spomen blaženoga Lovre mučenika tvoga da se tako radujemo njegovoj nebeskoj slavi.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, Gospodine, Bože naš, kao što se radujemo vremenitoj spomen-slavi blaženog Lovre, Tvoga mučenika,' tako da se veselimo i u vječnom gledanju njegovu, po G. n.","knRef":"Kniewald 1942, str. 674–675 (snimka 338) (OCR)"}},"variants":{"paschal":{}}});
